import {
  HomeOutlined,
  MenuFoldOutlined,
  MenuUnfoldOutlined,
  SettingOutlined,
  UserOutlined,
} from '@ant-design/icons'
import { Layout, Menu } from 'antd'
import React, { lazy, memo, Suspense, useCallback, useMemo, useState } from 'react'
import { useNavigate } from 'react-router-dom'

// Lazy load modals since they're not needed until user clicks
const PermissionsModal = lazy(() => import('../modals/AccountInfoModal.jsx'))
const AccountSettingsModal = lazy(() => import('../modals/AccountSettingsModal.jsx'))

const { Sider } = Layout

// Memoized styles to prevent object recreation
const siderStyle = { position: 'sticky', top: 0, height: '100vh' }

function Sidebar({ user }) {
  const [collapsed, setCollapsed] = useState(false)
  const [permissionsModalVisible, setPermissionsModalVisible] = useState(false)
  const [settingsModalVisible, setSettingsModalVisible] = useState(false)
  const navigate = useNavigate()

  const toggleCollapse = useCallback(() => setCollapsed((prev) => !prev), [])
  const goHome = useCallback(() => navigate('/campaign-tools'), [navigate])
  const togglePermissionsModal = useCallback(() => setPermissionsModalVisible((prev) => !prev), [])
  const toggleSettingsModal = useCallback(() => setSettingsModalVisible((prev) => !prev), [])
  const closePermissionsModal = useCallback(() => setPermissionsModalVisible(false), [])
  const closeSettingsModal = useCallback(() => setSettingsModalVisible(false), [])

  const siderWidth = useMemo(() => (collapsed ? 50 : 150), [collapsed])

  // Memoize menu items to prevent recreation
  const menuItems = useMemo(() => [
    {
      key: '1',
      icon: collapsed ? <MenuUnfoldOutlined /> : <MenuFoldOutlined />,
      label: collapsed ? 'Expand' : 'Collapse',
      onClick: toggleCollapse,
    },
    {
      key: '2',
      icon: <HomeOutlined />,
      label: 'Home',
      onClick: goHome,
    },
    {
      key: '3',
      icon: <UserOutlined />,
      label: 'Account',
      onClick: togglePermissionsModal,
    },
    {
      key: '4',
      icon: <SettingOutlined />,
      label: 'Settings',
      onClick: toggleSettingsModal,
    },
  ], [collapsed, toggleCollapse, goHome, togglePermissionsModal, toggleSettingsModal])

  return (
    <Sider
      trigger={null}
      collapsed={collapsed}
      width={siderWidth}
      style={siderStyle}
    >
      <Menu
        theme="dark"
        mode="vertical"
        defaultSelectedKeys={['1']}
        items={menuItems}
      />
      {/* Only render modals when visible to avoid unnecessary DOM nodes */}
      {permissionsModalVisible && (
        <Suspense fallback={null}>
          <PermissionsModal
            visible={permissionsModalVisible}
            onClose={closePermissionsModal}
            user={user}
          />
        </Suspense>
      )}
      {settingsModalVisible && (
        <Suspense fallback={null}>
          <AccountSettingsModal
            visible={settingsModalVisible}
            onCancel={closeSettingsModal}
          />
        </Suspense>
      )}
    </Sider>
  )
}

export default memo(Sidebar)
